// cox regression for survival data (negative values mean they are censored)
class CoxRegression : public ObjFunction {
 public:
  std::set<std::string> Configure(Args const&) override { return {}; }
  [[nodiscard]] ObjInfo Task() const override { return ObjInfo::kRegression; }
  void InitEstimation(MetaInfo const& info, linalg::Vector<float>* base_score) const override {
    *base_score = linalg::Zeros<float>(this->ctx_, this->Targets(info));
    this->PredTransform(base_score->Data());
  }

  void GetGradient(const HostDeviceVector<bst_float>& preds, const MetaInfo& info, int,
                   linalg::Matrix<GradientPair>* out_gpair) override {
    CHECK_NE(info.labels.Size(), 0U) << "label set cannot be empty";
    CHECK_EQ(preds.Size(), info.labels.Size()) << "labels are not correctly provided";
    const auto& preds_h = preds.HostVector();
    out_gpair->Reshape(info.num_row_, this->Targets(info));
    auto gpair = out_gpair->HostView();
    const std::vector<size_t>& label_order = info.LabelAbsSort(ctx_);

    const omp_ulong ndata = static_cast<omp_ulong>(preds_h.size());  // NOLINT(*)
    const bool is_null_weight = info.weights_.Size() == 0;
    if (!is_null_weight) {
      CHECK_EQ(info.weights_.Size(), ndata)
          << "Number of weights should be equal to number of data points.";
    }

    // pre-compute a sum
    double exp_p_sum = 0;  // we use double because we might need the precision with large datasets
    for (omp_ulong i = 0; i < ndata; ++i) {
      exp_p_sum += std::exp(preds_h[label_order[i]]);
    }

    // start calculating grad and hess
    const auto& labels = info.labels.HostView();
    double r_k = 0;
    double s_k = 0;
    double last_exp_p = 0.0;
    double last_abs_y = 0.0;
    double accumulated_sum = 0;
    for (omp_ulong i = 0; i < ndata; ++i) {  // NOLINT(*)
      const size_t ind = label_order[i];
      const double p = preds_h[ind];
      const double exp_p = std::exp(p);
      const double w = info.GetWeight(ind);
      const double y = labels(ind);
      const double abs_y = std::abs(y);

      // only update the denominator after we move forward in time (labels are sorted)
      // this is Breslow's method for ties
      accumulated_sum += last_exp_p;
      if (last_abs_y < abs_y) {
        exp_p_sum -= accumulated_sum;
        accumulated_sum = 0;
      } else {
        CHECK(last_abs_y <= abs_y) << "CoxRegression: labels must be in sorted order, "
                                   << "MetaInfo::LabelArgsort failed!";
      }

      if (y > 0) {
        r_k += 1.0 / exp_p_sum;
        s_k += 1.0 / (exp_p_sum * exp_p_sum);
      }

      const double grad = exp_p * r_k - static_cast<bst_float>(y > 0);
      const double hess = exp_p * r_k - exp_p * exp_p * s_k;
      gpair(ind) = GradientPair(grad * w, hess * w);

      last_abs_y = abs_y;
      last_exp_p = exp_p;
    }
  }
  void PredTransform(HostDeviceVector<bst_float>* io_preds) const override {
    common::Transform<>::Init(
        [] XGBOOST_DEVICE(size_t i, common::Span<bst_float> preds) { preds[i] = expf(preds[i]); },
        common::Range{0, static_cast<int64_t>(io_preds->Size())}, this->ctx_->Threads(),
        io_preds->Device())
        .Eval(io_preds);
  }
  void EvalTransform(HostDeviceVector<bst_float>* io_preds) override { PredTransform(io_preds); }
  void ProbToMargin(linalg::Vector<float>* base_score) const override {
    ProbToMarginImpl(this->ctx_, base_score, [] XGBOOST_DEVICE(float v) { return std::log(v); });
  }
  [[nodiscard]] const char* DefaultEvalMetric() const override { return "cox-nloglik"; }

  void SaveConfig(Json* p_out) const override {
    auto& out = *p_out;
    out["name"] = String("survival:cox");
  }
  void LoadConfig(Json const&) override {}
};

// register the objective function
XGBOOST_REGISTER_OBJECTIVE(CoxRegression, "survival:cox")
    .describe(
        "Cox regression for censored survival data (negative labels are considered censored).")
    .set_body([]() { return new CoxRegression(); });

enum class CensoringType : uint8_t {
  kUncensored, kRightCensored, kLeftCensored, kIntervalCensored
};

namespace aft {

// Allowable range for gradient and hessian. Used for regularization
constexpr double kMinGradient = -15.0;
constexpr double kMaxGradient = 15.0;
constexpr double kMinHessian = 1e-16;  // Ensure that no data point gets zero hessian
constexpr double kMaxHessian = 15.0;

constexpr double kEps = 1e-12;  // A denominator in a fraction should not be too small

// Clip (limit) x to fit range [x_min, x_max].
// If x < x_min, return x_min; if x > x_max, return x_max; if x_min <= x <= x_max, return x.
// This function assumes x_min < x_max; behavior is undefined if this assumption does not hold.
XGBOOST_DEVICE
inline double Clip(double x, double x_min, double x_max) {
  if (x < x_min) {
    return x_min;
  }
  if (x > x_max) {
    return x_max;
  }
  return x;

struct AFTParam : public XGBoostParameter<AFTParam> {
  /*! \brief Choice of probability distribution for the noise term in AFT */
  ProbabilityDistributionType aft_loss_distribution;
  /*! \brief Scaling factor to be applied to the distribution */
  float aft_loss_distribution_scale;
  DMLC_DECLARE_PARAMETER(AFTParam) {
    DMLC_DECLARE_FIELD(aft_loss_distribution)
        .set_default(ProbabilityDistributionType::kNormal)
        .add_enum("normal", ProbabilityDistributionType::kNormal)
        .add_enum("logistic", ProbabilityDistributionType::kLogistic)
        .add_enum("extreme", ProbabilityDistributionType::kExtreme)
        .describe("Choice of distribution for the noise term in "
                  "Accelerated Failure Time model");
    DMLC_DECLARE_FIELD(aft_loss_distribution_scale)
        .set_default(1.0f)
        .describe("Scaling factor used to scale the distribution in "
                  "Accelerated Failure Time model");
  }
};

/*! \brief The AFT loss function */
template<typename Distribution>
struct AFTLoss {
  XGBOOST_DEVICE inline static
  double Loss(double y_lower, double y_upper, double y_pred, double sigma) {
    const double log_y_lower = log(y_lower);
    const double log_y_upper = log(y_upper);

    double cost;

    if (y_lower == y_upper) {  // uncensored
      const double z = (log_y_lower - y_pred) / sigma;
      const double pdf = Distribution::PDF(z);
      // Regularize the denominator with eps, to avoid INF or NAN
      cost = -log(fmax(pdf / (sigma * y_lower), aft::kEps));
    } else {  // censored; now check what type of censorship we have
      double z_u, z_l, cdf_u, cdf_l;
      if (isinf(y_upper)) {  // right-censored
        cdf_u = 1;
      } else {  // left-censored or interval-censored
        z_u = (log_y_upper - y_pred) / sigma;
        cdf_u = Distribution::CDF(z_u);
      }
      if (y_lower <= 0.0) {  // left-censored
        cdf_l = 0;

  }
  gradient = numerator / denominator;
  if (denominator < aft::kEps && (isnan(gradient) || isinf(gradient))) {
    gradient = aft::GetLimitGradAtInfPred<Distribution>(censor_type, z_sign, sigma);
  }

  return aft::Clip(gradient, aft::kMinGradient, aft::kMaxGradient);
}

XGBOOST_DEVICE inline static
double Hessian(double y_lower, double y_upper, double y_pred, double sigma) {
  const double log_y_lower = log(y_lower);
  const double log_y_upper = log(y_upper);
  double numerator, denominator, hessian;  // numerator and denominator of hessian
  CensoringType censor_type;
  bool z_sign;  // sign of z-score

  if (y_lower == y_upper) {  // uncensored
    const double z = (log_y_lower - y_pred) / sigma;
    const double pdf = Distribution::PDF(z);
    const double grad_pdf = Distribution::GradPDF(z);
    const double hess_pdf = Distribution::HessPDF(z);
    censor_type = CensoringType::kUncensored;
    numerator = -(pdf * hess_pdf - grad_pdf * grad_pdf);
    denominator = sigma * sigma * pdf * pdf;
    z_sign = (z > 0);
  } else {  // censored; now check what type of censorship we have
    double z_u = 0.0, z_l = 0.0, grad_pdf_u, grad_pdf_l, pdf_u, pdf_l, cdf_u, cdf_l;
    censor_type = CensoringType::kIntervalCensored;
    if (isinf(y_upper)) {  // right-censored
      pdf_u = 0;
      cdf_u = 1;
      grad_pdf_u = 0;
      censor_type = CensoringType::kRightCensored;
    } else {  // interval-censored or left-censored
      z_u = (log_y_upper - y_pred) / sigma;
      pdf_u = Distribution::PDF(z_u);
      cdf_u = Distribution::CDF(z_u);
      grad_pdf_u = Distribution::GradPDF(z_u);
    }
    if (y_lower <= 0.0) {  // left-censored
      pdf_l = 0;
      cdf_l = 0;
      grad_pdf_l = 0;
      censor_type = CensoringType::kLeftCensored;
    } else {  // interval-censored or right-censored
      z_l = (log_y_lower - y_pred) / sigma;
      pdf_l = Distribution::PDF(z_l);
      cdf_l = Distribution::CDF(z_l);
      grad_pdf_l = Distribution::GradPDF(z_l);
    }
    const double cdf_diff = cdf_u - cdf_l;
    const double pdf_diff = pdf_u - pdf_l;
    const double grad_diff = grad_pdf_u - grad_pdf_l;
    const double sqrt_denominator = sigma * cdf_diff;
    z_sign = (z_u > 0 || z_l > 0);
    numerator = -(cdf_diff * grad_diff - pdf_diff * pdf_diff);
    denominator = sqrt_denominator * sqrt_denominator;
  }
  hessian = numerator / denominator;
  if (denominator < aft::kEps && (isnan(hessian) || isinf(hessian))) {
    hessian = aft::GetLimitHessAtInfPred<Distribution>(censor_type, z_sign, sigma);
  }

  return aft::Clip(hessian, aft::kMinHessian, aft::kMaxHessian);

template <typename Distribution>
void AFTGradientCpuImpl(HostDeviceVector<float> const& preds, MetaInfo const& info, float scale,
                        std::int32_t n_threads, linalg::Matrix<GradientPair>* out_gpair) {
  auto predt = preds.ConstHostSpan();
  auto lower = info.labels_lower_bound_.ConstHostSpan();
  auto upper = info.labels_upper_bound_.ConstHostSpan();
  auto weights = info.weights_.ConstHostSpan();
  auto gpair = out_gpair->HostView();
  bool is_null_weight = weights.empty();
  common::ParallelFor(predt.size(), n_threads, [=](std::size_t i) mutable {
    auto grad = static_cast<float>(
        common::AFTLoss<Distribution>::Gradient(lower[i], upper[i], predt[i], scale));
    auto hess = static_cast<float>(
        common::AFTLoss<Distribution>::Hessian(lower[i], upper[i], predt[i], scale));
    auto weight = is_null_weight ? 1.0f : weights[i];
    gpair(i, 0) = {grad * weight, hess * weight};
  });
}

void AFTGradientCpu(Context const* ctx, HostDeviceVector<float> const& preds, MetaInfo const& info,
                    common::ProbabilityDistributionType distribution, float scale,
                    linalg::Matrix<GradientPair>* out_gpair) {
  out_gpair->SetDevice(DeviceOrd::CPU());
  out_gpair->Reshape(preds.Size(), 1);
  switch (distribution) {
    case common::ProbabilityDistributionType::kNormal:
      AFTGradientCpuImpl<common::NormalDistribution>(preds, info, scale, ctx->Threads(), out_gpair);
      break;
    case common::ProbabilityDistributionType::kLogistic:
      AFTGradientCpuImpl<common::LogisticDistribution>(preds, info, scale, ctx->Threads(),
                                                       out_gpair);
      break;
    case common::ProbabilityDistributionType::kExtreme:
      AFTGradientCpuImpl<common::ExtremeDistribution>(preds, info, scale, ctx->Threads(),
                                                      out_gpair);
      break;
    default:
      LOG(FATAL) << "Unrecognized distribution";
  }
}

void AFTPredTransformCpu(Context const* ctx, HostDeviceVector<float>* predictions) {
  auto values = predictions->HostSpan();
  common::ParallelFor(values.size(), ctx->Threads(),
                      [=](std::size_t i) { values[i] = std::exp(values[i]); });
}

void AFTProbToMarginCpu(Context const*, linalg::Vector<float>* base_score) {
  auto values = base_score->HostView();
  for (std::size_t i{0}; i < values.Size(); ++i) {
    values(i) = std::log(values(i));
  }

class AFTObj : public ObjFunction {
 public:
  std::set<std::string> Configure(Args const& args) override {
    return UpdateAndGetUsedParameters(&param_, args);
  }
  ObjInfo Task() const override { return ObjInfo::kSurvival; }

  void GetGradient(HostDeviceVector<float> const& preds, MetaInfo const& info, std::int32_t,
                   linalg::Matrix<GradientPair>* out_gpair) override {
    auto ndata = preds.Size();
    CHECK_EQ(info.labels_lower_bound_.Size(), ndata);
    CHECK_EQ(info.labels_upper_bound_.Size(), ndata);
    if (!info.weights_.Empty()) {
      CHECK_EQ(info.weights_.Size(), ndata)
          << "Number of weights should be equal to number of data points.";
    }
    common::DispatchKernel<AFTGradientKernel>(ctx_, preds, info, param_.aft_loss_distribution,
                                              param_.aft_loss_distribution_scale, out_gpair);
  }

  void PredTransform(HostDeviceVector<float>* predictions) const override {
    // Trees give us a prediction in log scale, so exponentiate.
    common::DispatchKernel<AFTPredTransformKernel>(ctx_, predictions);
  }
  // Do nothing here, since the AFT metric expects untransformed prediction scores.
  void EvalTransform(HostDeviceVector<float>*) override {}
  void ProbToMargin(linalg::Vector<float>* base_score) const override {
    common::DispatchKernel<AFTProbToMarginKernel>(ctx_, base_score);
  }
  char const* DefaultEvalMetric() const override { return "aft-nloglik"; }

  void SaveConfig(Json* out) const override {
    (*out)["name"] = String("survival:aft");
    (*out)["aft_loss_param"] = ToJson(param_);
  }
  void LoadConfig(Json const& in) override { FromJson(in["aft_loss_param"], &param_); }
  Json DefaultMetricConfig() const override {
    Json config{Object{}};
    config["name"] = String{this->DefaultEvalMetric()};
    config["aft_loss_param"] = ToJson(param_);
    return config;
  }

 private:
  common::AFTParam param_;

template <typename Distribution>
void AFTGradientCudaImpl(Context const* ctx, HostDeviceVector<float> const& preds,
                         MetaInfo const& info, float scale,
                         linalg::Matrix<GradientPair>* out_gpair) {
  auto device = ctx->Device();
  preds.SetDevice(device);
  info.labels_lower_bound_.SetDevice(device);
  info.labels_upper_bound_.SetDevice(device);
  info.weights_.SetDevice(device);
  auto predt = preds.ConstDeviceSpan();
  auto lower = info.labels_lower_bound_.ConstDeviceSpan();
  auto upper = info.labels_upper_bound_.ConstDeviceSpan();
  auto weights = info.weights_.ConstDeviceSpan();
  auto gpair = out_gpair->View(device);
  bool is_null_weight = weights.empty();
  dh::LaunchN(predt.size(), ctx->CUDACtx()->Stream(), [=] XGBOOST_DEVICE(std::size_t i) mutable {
    auto grad = static_cast<float>(
        common::AFTLoss<Distribution>::Gradient(lower[i], upper[i], predt[i], scale));
    auto hess = static_cast<float>(
        common::AFTLoss<Distribution>::Hessian(lower[i], upper[i], predt[i], scale));
    auto weight = is_null_weight ? 1.0f : weights[i];
    gpair(i, 0) = {grad * weight, hess * weight};
  });
}

void AFTGradientCuda(Context const* ctx, HostDeviceVector<float> const& preds, MetaInfo const& info,
                     common::ProbabilityDistributionType distribution, float scale,
                     linalg::Matrix<GradientPair>* out_gpair) {
  auto device = ctx->Device();
  CHECK(device.IsCUDA());
  out_gpair->SetDevice(device);
  out_gpair->Reshape(preds.Size(), 1);
  switch (distribution) {
    case common::ProbabilityDistributionType::kNormal:
      AFTGradientCudaImpl<common::NormalDistribution>(ctx, preds, info, scale, out_gpair);
      break;
    case common::ProbabilityDistributionType::kLogistic:
      AFTGradientCudaImpl<common::LogisticDistribution>(ctx, preds, info, scale, out_gpair);
      break;
    case common::ProbabilityDistributionType::kExtreme:
      AFTGradientCudaImpl<common::ExtremeDistribution>(ctx, preds, info, scale, out_gpair);
      break;
    default:
      LOG(FATAL) << "Unrecognized distribution";
  }
}

void AFTPredTransformCuda(Context const* ctx, HostDeviceVector<float>* predictions) {
  auto device = ctx->Device();
  predictions->SetDevice(device);
  auto values = predictions->DeviceSpan();
  dh::LaunchN(values.size(), ctx->CUDACtx()->Stream(),
              [=] XGBOOST_DEVICE(std::size_t i) { values[i] = expf(values[i]); });
}

void AFTProbToMarginCuda(Context const* ctx, linalg::Vector<float>* base_score) {
  auto values = base_score->View(ctx->Device());
  dh::LaunchN(values.Size(), ctx->CUDACtx()->Stream(),
              [=] XGBOOST_DEVICE(std::size_t i) mutable { values(i) = logf(values(i)); });
}

